describe("splitLeg", () => {
    const buy: PlanLeg = { side: "buy", assetId: "bitcoin", qty: 1, notionalUsd: 100000, reason: "harvest_rebuy" };
    it("keeps a leg that fits", () => {
        expect(splitLeg(buy, 200000)).toEqual([buy]);
    });
    it("splits a buy evenly; pieces sum to the original and each fits", () => {
        const pieces = splitLeg(buy, 30000);
        expect(pieces).toHaveLength(4);
        expect(sum(pieces.map((p) => p.notionalUsd))).toBeCloseTo(100000);
        expect(sum(pieces.map((p) => p.qty))).toBeCloseTo(1);
        for (const p of pieces)
            expect(p.notionalUsd).toBeLessThanOrEqual(30000);
    });
    it("splits a harvest sell along its lots, pro-rating a lot larger than a piece, and carries per-lot P/L", () => {
        const sell: PlanLeg = {
            side: "sell", assetId: "bitcoin", qty: 1.6, notionalUsd: 80000, reason: "harvest",
            lotIds: ["A", "B"], realizedStUsd: -4000, realizedLtUsd: -6000,
            harvestLots: [
                { lotId: "A", qty: 0.4, basisPerUnitUsd: 60000, stOrLt: "st" },
                { lotId: "B", qty: 1.2, basisPerUnitUsd: 55000, stOrLt: "lt" },
            ],
        };
        const pieces = splitLeg(sell, 30000);
        expect(pieces.map((p) => p.lotIds)).toEqual([["A"], ["B"], ["B"]]);
        for (const p of pieces)
            if (p.harvestLots!.some((l) => l.lotId === "B"))
                expect(p.lotIds).toEqual(["B"]);
        expect(sum(pieces.map((p) => p.qty))).toBeCloseTo(1.6);
        for (const p of pieces)
            expect(p.notionalUsd).toBeLessThanOrEqual(30000 + 1e-6);
        expect(sum(pieces.map((p) => p.realizedStUsd ?? 0))).toBeCloseTo(-4000);
        expect(sum(pieces.map((p) => p.realizedLtUsd ?? 0))).toBeCloseTo(-6000);
        const qtyOf = (id: string) => sum(pieces.flatMap((p) => p.harvestLots!.filter((l) => l.lotId === id).map((l) => l.qty)));
        expect(qtyOf("A")).toBeCloseTo(0.4);
        expect(qtyOf("B")).toBeCloseTo(1.2);
    });
});
